"""Rate-limiting decorator for request handlers."""

import functools
import logging
from typing import Callable, TypeVar

from manager import BucketManager

logger = logging.getLogger(__name__)

F = TypeVar("F", bound=Callable[..., object])


class RateLimitExceeded(Exception):
    """Raised when a request is rejected because it exceeded its rate limit."""

    def __init__(self, key: str) -> None:
        super().__init__(f"rate limit exceeded for {key!r}")
        self.key = key


def rate_limited(manager: BucketManager, key_func: Callable[..., str], cost: float = 1.0) -> Callable[[F], F]:
    """Decorate a handler so calls are throttled per key_func(*args, **kwargs).

    ``key_func`` receives the same arguments as the wrapped handler and
    must return a string identifying the caller (e.g. an API key or
    client IP). If the caller has enough tokens the handler runs
    normally; otherwise RateLimitExceeded is raised and the handler is
    never called.
    """

    def decorator(func: F) -> F:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = key_func(*args, **kwargs)
            if not manager.allow(key, cost):
                logger.warning("throttled request for %s", key)
                raise RateLimitExceeded(key)
            return func(*args, **kwargs)

        return wrapper  # type: ignore[return-value]

    return decorator


def build_default_manager() -> BucketManager:
    """Construct a manager with sensible defaults: burst of 20, 10 req/s refill, 1h idle cleanup."""
    return BucketManager(capacity=20.0, refill_rate=10.0, idle_timeout=3600.0)


def client_ip_key(request) -> str:
    """Default key function: rate limit per client IP address."""
    return request.remote_addr
